/* ta_msg_tel_dropped_size: see ring_proto.h. */
ta_result ta_msg_tel_dropped_size(const ta_msg_tel_dropped *data, uint32_t *size) {
    (void)data;
    *size = 48;
    return TA_OK;
}

/* ta_msg_tel_dropped_write: see ring_proto.h. */
ta_result ta_msg_tel_dropped_write(const ta_msg_tel_dropped *data, const ta_ring_reservation *to) {
    ta_msg_tel_dropped_wire wire;
    uint32_t size = 0;
    ta_record_tail tail = { to->bytes, (uint32_t)sizeof wire };
    ta_result result = ta_msg_tel_dropped_size(data, &size);
    if (result != TA_OK) {
        return result;
    }
    if (to->bytes == NULL ||
        to->size != size ||
        (data->head.flags & (uint16_t)~0x0300u) != 0) {
        return TA_ERR_INVALID;
    }
    ta_mem_zero(&wire, sizeof wire);
    wire.header = (ta_msg_wire_header){ .kind = TA_MSG_TEL_DROPPED, .flags = data->head.flags, .size = size,
                                        .seq = to->seq, .session = data->head.session, .at = data->head.at };
    wire.count = data->count;
    wire.first_seq = data->first_seq;
    ta_mem_copy(to->bytes, &wire, sizeof wire);
    ta_mem_zero(to->bytes + tail.at, size - tail.at);
    return TA_OK;
}

/* ta_msg_tel_dropped_get: see ring_proto.h. */
ta_result ta_msg_tel_dropped_get(const ta_record *record, ta_msg_tel_dropped *out) {
    ta_msg_tel_dropped value;
    if (record->kind != TA_MSG_TEL_DROPPED) {
        return TA_ERR_INVALID;
    }
    ta_mem_zero(&value, sizeof value);
    value.head.flags = ta_record_u16(record, TA_RECORD_AT_FLAGS);
    value.head.session = ta_record_u64(record, TA_RECORD_AT_SESSION);
    value.head.at = ta_record_u64(record, TA_RECORD_AT_TIME);
    value.count = ta_record_u64(record, 32);
    value.first_seq = ta_record_u64(record, 40);
    *out = value;
    return TA_OK;
}

